package dev.starcrownqa;
import dev.starcrown.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.InteractionHand;
@GameTestHolder("starcrownqa") @PrefixGameTestTemplate(false)
public final class TemperanceTests {
 @GameTest(template="empty",timeoutTicks=100) public static void foodDurabilityAndRelease(GameTestHelper h){var p=ChastityTests.player(h);try{ChastityTests.equip(p);YuleTemperance.enforce(p);var f=p.getFoodData();f.setFoodLevel(1);f.setSaturation(0);f.addExhaustion(100);h.assertTrue(f.getFoodLevel()==20&&f.getSaturationLevel()==20&&f.getExhaustionLevel()==0,"food locked full");var steak=new ItemStack(Items.COOKED_BEEF,3);p.setItemInHand(InteractionHand.MAIN_HAND,steak);p.startUsingItem(InteractionHand.MAIN_HAND);h.assertTrue(!p.isUsingItem(),"steak cannot start");p.eat(p.level(),steak);h.assertTrue(steak.getCount()==3,"direct eat forbidden");h.assertTrue(!YuleTemperance.foodDenied(p,new ItemStack(Items.BREAD)),"bread allowed");var tool=new ItemStack(Items.IRON_PICKAXE);p.setItemInHand(InteractionHand.MAIN_HAND,tool);tool.hurtAndBreak(9999,p,e->{});tool.setDamageValue(999);h.assertTrue(tool.getCount()==1&&tool.getDamageValue()==0,"held tool cannot break or gain damage");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);f.setFoodLevel(2);tool.setDamageValue(5);h.assertTrue(f.getFoodLevel()==2&&tool.getDamageValue()==5,"unequip releases restrictions");h.succeed();}finally{ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void stackConservation(GameTestHelper h){var p=ChastityTests.player(h);try{ChastityTests.equip(p);p.getInventory().items.set(0,new ItemStack(Items.COBBLESTONE,64));YuleTemperance.enforce(p);int total=0;for(int i=0;i<9;i++){var s=p.getInventory().getItem(i);if(s.is(Items.COBBLESTONE)){total+=s.getCount();h.assertTrue(s.getCount()<=16,"all redistributed stacks capped");}}h.assertTrue(total==64,"overflow conserved");h.assertTrue(new ItemStack(Items.COBBLESTONE).getMaxStackSize()==64,"external stacks unaffected");var s=p.getInventory().getItem(0);s.shrink(1);h.assertTrue(s.getCount()==15,"manual transfers still consume");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);h.assertTrue(s.getMaxStackSize()==64,"unequip removes cap");h.succeed();}finally{ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void actualMiningQuota(GameTestHelper h){var p=ChastityTests.player(h);var pos=p.blockPosition().offset(2,0,0);try{ChastityTests.equip(p);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));for(int i=0;i<10;i++){p.serverLevel().setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());h.assertTrue(p.gameMode.destroyBlock(pos),"first ten breaks succeed "+i);}h.assertTrue(YuleTemperance.used(p,pos,Blocks.STONE)==10,"successful breaks counted");p.serverLevel().setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());h.assertTrue(!p.gameMode.destroyBlock(pos)&&p.serverLevel().getBlockState(pos).is(Blocks.STONE),"eleventh blocked");h.assertTrue(!YuleTemperance.denied(p,pos.offset(32,0,0)),"different chunk independent");p.serverLevel().setBlockAndUpdate(pos,Blocks.DIRT.defaultBlockState());h.assertTrue(p.gameMode.destroyBlock(pos),"different type independent");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);p.serverLevel().setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());h.assertTrue(p.gameMode.destroyBlock(pos),"unequip allows mining");ChastityTests.equip(p);h.assertTrue(YuleTemperance.used(p,pos,Blocks.STONE)==10,"count survives unequip");h.succeed();}finally{p.serverLevel().setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void bowAndPearl(GameTestHelper h){var p=ChastityTests.player(h);try{ChastityTests.equip(p);YuleTemperance.bind(p);var bow=new ItemStack(Items.BOW);p.setItemInHand(InteractionHand.MAIN_HAND,bow);h.assertTrue(p.getProjectile(bow).is(Items.ARROW),"no-ammo bow gets virtual arrow");int before=p.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.AbstractArrow.class,p.getBoundingBox().inflate(5)).size();Items.BOW.releaseUsing(bow,p.level(),p,71980);var arrows=p.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.AbstractArrow.class,p.getBoundingBox().inflate(5));h.assertTrue(arrows.size()>before,"bow actually fires");for(var a:arrows){h.assertTrue(a.pickup==net.minecraft.world.entity.projectile.AbstractArrow.Pickup.CREATIVE_ONLY,"free arrow cannot duplicate");a.discard();}h.assertTrue(bow.getDamageValue()==0,"bow no durability loss");var pearls=new ItemStack(Items.ENDER_PEARL,4);p.setItemInHand(InteractionHand.MAIN_HAND,pearls);Items.ENDER_PEARL.use(p.level(),p,InteractionHand.MAIN_HAND);h.assertTrue(pearls.getCount()==4,"pearl not consumed");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);Items.ENDER_PEARL.use(p.level(),p,InteractionHand.MAIN_HAND);h.assertTrue(pearls.getCount()==3,"normal pearl consumes after unequip");h.succeed();}finally{ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void blocksAndRockets(GameTestHelper h){var p=ChastityTests.player(h);var base=p.blockPosition().offset(3,0,0);var l=p.serverLevel();try{ChastityTests.equip(p);l.setBlockAndUpdate(base,Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(base.above(),Blocks.AIR.defaultBlockState());var stack=new ItemStack(Items.COBBLESTONE,4);p.setItemInHand(InteractionHand.MAIN_HAND,stack);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(base).add(0,.5,0),net.minecraft.core.Direction.UP,base,false);var ctx=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,hit);h.assertTrue(((BlockItem)Items.COBBLESTONE).place(new net.minecraft.world.item.context.BlockPlaceContext(ctx)).consumesAction(),"block placement succeeds");h.assertTrue(l.getBlockState(base.above()).is(Blocks.COBBLESTONE)&&stack.getCount()==4,"placed block free");var rockets=new ItemStack(Items.FIREWORK_ROCKET,4);p.setItemInHand(InteractionHand.MAIN_HAND,rockets);ctx=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,hit);h.assertTrue(Items.FIREWORK_ROCKET.useOn(ctx).consumesAction()&&rockets.getCount()==4,"ground rocket free");p.startFallFlying();Items.FIREWORK_ROCKET.use(l,p,InteractionHand.MAIN_HAND);h.assertTrue(rockets.getCount()==4,"flight rocket free");p.stopFallFlying();p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);Items.FIREWORK_ROCKET.useOn(ctx);h.assertTrue(rockets.getCount()==3,"rocket consumption restored");h.succeed();}finally{l.setBlockAndUpdate(base.above(),Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(base,Blocks.AIR.defaultBlockState());ChastityTests.close(p);}}
}
